[CmdletBinding()]
param([ValidateSet('Prepare','Start','Stop','Status')][string]$Action='Prepare',
    [string]$RunId='e5b-20261031',[int]$Port=8096,
    [string]$Baseline='outputs/entity-generation-g1-extension/e5-h/e5h-20261031')
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
if($RunId -notmatch '^[A-Za-z0-9_-]+$'){throw 'Invalid RunId'}
$repo=Split-Path $PSScriptRoot -Parent
$base=[IO.Path]::GetFullPath((Join-Path $repo $Baseline));$local="$base/repository"
$out=Join-Path $repo "outputs/entity-generation-g1-extension/e5-b/$RunId"
$java='C:/Program Files/Axiom/AxiomJDK-21';$env:JAVA_HOME=$java
$mvn='C:/Program Files/JetBrains/IntelliJ IDEA Community Edition 2025.2.3/plugins/maven/lib/maven3/bin/mvn.cmd'
function Text($p,$v){[IO.File]::WriteAllText($p,$v,[Text.UTF8Encoding]::new($false))}
New-Item -ItemType Directory -Path $out -Force|Out-Null
if($Action -in @('Stop','Status')){
    if(!(Test-Path "$out/server-state.json")){Write-Output 'Not started';return}
    $s=Get-Content "$out/server-state.json" -Raw|ConvertFrom-Json;$p=Get-Process -Id $s.pid -ErrorAction SilentlyContinue
    if($p -and ($p.Path -ne $s.executable -or $p.StartTime.ToUniversalTime().Ticks -ne $s.startTicks)){throw 'PID identity mismatch'}
    if($Action -eq 'Stop' -and $p){Stop-Process -Id $p.Id};Write-Output "Running: $([bool]$p -and $Action -ne 'Stop')";return
}
foreach($file in (Get-Content "$base/build-complete.json" -Raw|ConvertFrom-Json)){
    if((Get-FileHash -LiteralPath $file.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $file.sha256){throw "E5.H artifact drift: $($file.path)"}
}
if($Action -eq 'Prepare'){
    $project="$out/project";New-Item -ItemType Directory "$project/src/main/java","$out/adapter-classes","$out/classes" -Force|Out-Null
    $cases=@('scalar-document','reference-catalog','reference-document','owned-catalog','sections-catalog-2','sections-document-2','sections-owned-catalog-2')
    $sources=[Collections.Generic.List[object]]::new()
    foreach($case in $cases){$result=Get-Content "$base/actual/$case/result.json" -Raw|ConvertFrom-Json;$plan=Get-Content "$($result.input)/reviewed-plan.json" -Raw|ConvertFrom-Json
        foreach($file in $plan.files){$src="$base/actual/$case/project/src/main/java/$($file.relativePath)";if((Get-FileHash $src -Algorithm SHA256).Hash.ToLowerInvariant() -ne $file.sha256){throw 'Generated byte drift'}
            $dest="$project/src/main/java/$($file.relativePath)";New-Item -ItemType Directory (Split-Path $dest -Parent) -Force|Out-Null;Copy-Item $src $dest -Force;$sources.Add(@{case=$case;relativePath=$file.relativePath;sha256=$file.sha256})}
    }
    $sources|ConvertTo-Json|Set-Content "$out/generated-bindings.json" -Encoding utf8
    New-Item -ItemType Directory "$out/adapter-classes/org/ip/views" -Force|Out-Null
    Get-ChildItem -LiteralPath "$out/adapter-classes/org/ip/views" -File -Filter '*.class'|ForEach-Object{Remove-Item -LiteralPath $_.FullName}
    Copy-Item "$base/ui/build-app/classes/org/ip/views/admin" "$out/adapter-classes/org/ip/views/" -Recurse -Force
    $pom='<project xmlns="http://maven.apache.org/POM/4.0.0"><modelVersion>4.0.0</modelVersion><parent><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-parent</artifactId><version>4.0.6</version><relativePath/></parent><groupId>org.ipro.evidence</groupId><artifactId>e5-browser</artifactId><version>1</version><properties><java.version>21</java.version></properties><dependencyManagement><dependencies><dependency><groupId>org.ipro</groupId><artifactId>platform-bom</artifactId><version>1.0-SNAPSHOT</version><type>pom</type><scope>import</scope></dependency></dependencies></dependencyManagement><dependencies>'
    foreach($id in @('platform-backend-starter','platform-vaadin','entity-design-core','entity-design-json','entity-design-runtime')){$pom+="<dependency><groupId>org.ipro</groupId><artifactId>$id</artifactId><version>1.0-SNAPSHOT</version></dependency>"}
    $pom+='<dependency><groupId>org.ipro</groupId><artifactId>g1-reference-target</artifactId><version>1.0-E2</version></dependency><dependency><groupId>com.vaadin</groupId><artifactId>vaadin-spring-boot-starter</artifactId><version>25.1.6</version></dependency><dependency><groupId>com.vaadin</groupId><artifactId>vaadin-dev</artifactId><version>25.1.6</version></dependency><dependency><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-data-jpa</artifactId></dependency><dependency><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-validation</artifactId></dependency><dependency><groupId>org.springframework.boot</groupId><artifactId>spring-boot-starter-security</artifactId></dependency><dependency><groupId>com.h2database</groupId><artifactId>h2</artifactId><scope>runtime</scope></dependency></dependencies></project>'
    Text "$project/pom.xml" $pom
    & $mvn -B -ntp -s "$base/settings.xml" "-Dmaven.repo.local=$local" -f "$project/pom.xml" dependency:build-classpath "-Dmdep.outputFile=$out/classpath.txt" *> "$out/dependencies.log"
    if($LASTEXITCODE){throw 'Stand dependency resolution failed'}
    $cp="$out/adapter-classes;"+(Get-Content "$out/classpath.txt" -Raw).Trim()
    $argsJ=@('--release','21','-parameters','-encoding','UTF-8','-cp',('"'+$cp.Replace('\','/')+'"'),'-d',('"'+"$out/classes".Replace('\','/')+'"'))
    $argsJ+=@(Get-ChildItem "$PSScriptRoot/entity-generation-g1-browser","$project/src/main/java" -Recurse -Filter '*.java'|ForEach-Object{'"'+$_.FullName.Replace('\','/')+'"'})
    [IO.File]::WriteAllLines("$out/compile.args",$argsJ,[Text.UTF8Encoding]::new($false))
    & "$java/bin/javac.exe" "@$out/compile.args" *> "$out/compile.log"
    if($LASTEXITCODE){throw 'Stand compile failed'}
    Write-Output "Prepared: $out";return
}
if(!(Test-Path "$out/classes/org/ipro/e5browser/BrowserApplication.class")){throw 'Prepare first'}
$props=@("server.address=127.0.0.1","server.port=$Port","server.servlet.session.cookie.name=$RunId",'spring.application.name=e5-browser-isolated',
    'spring.datasource.url=jdbc:h2:mem:e5browser;DB_CLOSE_DELAY=-1','spring.datasource.username=sa','spring.datasource.password=',
    'spring.jpa.hibernate.ddl-auto=create-drop','spring.jpa.open-in-view=false','spring.main.banner-mode=off',
    'platform.subsystem-scan-package=com.example.generated','rls.dimension-scan-package=com.example.generated','settings.scan-package=org.ipro.e5browser.settings',
    'rls.write-boundary.enforced=true','ipro.telemetry.enabled=false','ipro.telemetry.db-journal=false','vaadin.launch-browser=false',
    'logging.level.org.atmosphere=warn')
Text "$out/application.properties" ($props -join "`n")
$cp="$out/classes;$out/adapter-classes;"+(Get-Content "$out/classpath.txt" -Raw).Trim()
$argsJava=@('-Dfile.encoding=UTF-8',('-De5.input="'+"$base/inputs".Replace('\','/')+'"'),'-cp',('"'+$cp.Replace('\','/')+'"'),'org.ipro.e5browser.BrowserApplication',('--spring.config.location=file:"'+"$out/application.properties".Replace('\','/')+'"'))
[IO.File]::WriteAllLines("$out/server.args",$argsJava,[Text.UTF8Encoding]::new($false))
$p=Start-Process -FilePath "$java/bin/java.exe" -ArgumentList ('@"'+"$out/server.args"+'"') -WorkingDirectory $repo -WindowStyle Hidden -PassThru -RedirectStandardOutput "$out/server.log" -RedirectStandardError "$out/server.err.log"
@{pid=$p.Id;executable=$p.Path;startTicks=$p.StartTime.ToUniversalTime().Ticks;url="http://127.0.0.1:$Port";baseline=$base}|ConvertTo-Json|Set-Content "$out/server-state.json" -Encoding utf8
Write-Output "Started isolated stand PID=$($p.Id) http://127.0.0.1:$Port"
